ITEM_CATEGORIES = {
    0: {"name": "Item", "name_pt": "Itens / Consumíveis", "table": ITEMS},
    1: {"name": "Weapon", "name_pt": "Armas", "table": WEAPONS},
    2: {"name": "Armor", "name_pt": "Armaduras", "table": ARMORS},
    3: {"name": "Accessory", "name_pt": "Acessórios", "table": ACCESSORIES},
}

def get_item_name(category_idx: int, item_id: int) -> str:
    cat = ITEM_CATEGORIES.get(category_idx)
    if not cat:
        return f"Unknown (0x{item_id:02X})"
    table = cat["table"]
    if 0 <= item_id < len(table):
        return table[item_id]
    return f"Item 0x{item_id:02X}"
